// NTC termometre: sıcaklığı Beta formülüyle hesaplar, eşiği geçince LED yakar.
// Modülde NTC ile 10 kΩ sabit direnç gerilim bölücü kurar; OUT bölücünün ortasıdır.
#include <math.h>

const int NTC_PIN = A0;
const int LED_PIN = 13;
const float BETA = 3950.0;        // NTC'nin Beta katsayısı (satıcının verisine bak)
const float T0 = 298.15;          // 25 °C, kelvin cinsinden; NTC bu sıcaklıkta 10 kΩ'dur
const float ESIK_C = 30.0;        // bu sıcaklığın üstünde LED yanar
const unsigned long BEKLE_MS = 1000;  // iki ölçüm arası bekleme

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int deger = analogRead(NTC_PIN);   // 0-1023
  deger = constrain(deger, 1, 1022); // 0 ve 1023'te formül sıfıra böler

  // Bölücüden NTC direncinin 10 kΩ'a oranını bul.
  float oran = deger / (1023.0 - deger);
  // Beta formülü: 1/T = 1/T0 + ln(R/R0) / B  (T kelvin)
  float kelvin = 1.0 / (1.0 / T0 + log(oran) / BETA);
  float sicaklik = kelvin - 273.15;

  bool sicak = sicaklik > ESIK_C;
  digitalWrite(LED_PIN, sicak ? HIGH : LOW);

  Serial.print("Sicaklik: ");
  Serial.print(sicaklik, 1);
  Serial.print(" C  LED: ");
  Serial.println(sicak ? "acik" : "kapali");
  delay(BEKLE_MS);
}
